#include "stdlib/math/base/special/sincospif.h"
#include "stdlib/math/base/special/absf.h"
#include "stdlib/math/base/special/sincosf.h"
#include "stdlib/math/base/special/floorf.h"
#include "stdlib/math/base/special/copysignf.h"
#include "stdlib/math/base/special/fmodf.h"
#include "stdlib/math/base/assert/is_infinitef.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/constants/float32/pi.h"

/**
* Simultaneously computes the sine and cosine of a number times π (single-precision).
*
* @param x         input value
* @param sine      destination to store the sine
* @param cosine    destination to store the cosine
*
* @example
* float x = 0.0f;
*
* float cosine;
* float sine;
* stdlib_base_sincospif( x, &sine, &cosine );
*/
void stdlib_base_sincospif( const float x, float* sine, float* cosine ) {
	float tmp;
	float ix;
	float ar;
	float r;

	if ( stdlib_base_is_nanf( x ) || stdlib_base_is_infinitef( x ) ) {
		*sine = 0.0f / 0.0f;   // NaN
		*cosine = 0.0f / 0.0f; // NaN
		return;
	}

	r = stdlib_base_fmodf( x, 2.0f );
	ar = stdlib_base_absf( r );

	if ( ar == 0.0f || ar == 1.0f ) {
		ix = stdlib_base_floorf( ar );
		*sine = stdlib_base_copysignf( 0.0f, r );
		*cosine = ( stdlib_base_fmodf( ix, 2.0f ) == 1.0f ) ? -1.0f : 1.0f;
		return;
	}

	if ( ar < 0.25f ) {
		stdlib_base_sincosf( STDLIB_CONSTANT_FLOAT32_PI * r, sine, cosine );
		return;
	}

	if ( ar < 0.75f ) {
		ar = 0.5f - ar;
		stdlib_base_sincosf( STDLIB_CONSTANT_FLOAT32_PI * ar, sine, cosine );
		tmp = *sine;
		*sine = stdlib_base_copysignf( *cosine, r );
		*cosine = tmp;
		return;
	}

	if ( ar < 1.25f ) {
		r = stdlib_base_copysignf( 1.0f, r ) - r;
		stdlib_base_sincosf( STDLIB_CONSTANT_FLOAT32_PI * r, sine, cosine );
		*cosine *= -1.0f;
		return;
	}

	if ( ar < 1.75f ) {
		ar -= 1.5f;
		stdlib_base_sincosf( STDLIB_CONSTANT_FLOAT32_PI * ar, sine, cosine );
		tmp = *sine;
		*sine = -stdlib_base_copysignf( *cosine, r );
		*cosine = tmp;
		return;
	}

	r -= stdlib_base_copysignf( 2.0f, r );
	stdlib_base_sincosf( STDLIB_CONSTANT_FLOAT32_PI * r, sine, cosine );
	return;
}
